165	/**
166	 * Run a build's parts in order so each part can only ADD to what earlier parts built: a write into a cell an earlier
167	 * part placed (air included, so no carving) is refused, counted, never thrown, so a later part can't knock holes in
168	 * a wall. Cells set before runParts (the ground) stay writable: farmland and paths may replace grass. With a palette
169	 * (palette.json, or its object: { roles: { role: [blocks] }, objects: [blocks] }), every block placed outside it is
170	 * reported. Prints one line per part, writes the reports to `report` (default parts-report.json; null for none) and
171	 * returns them.
172	 * roof: a roof spec (roof.json, as for `mcd roof --spec`) laid right after the FIRST part (the shell), so every later
173	 * part builds around the finished roof instead of the roof tool clearing the attic, gables and lofts after them. No
174	 * file yet (the roof part writes it, maybe in another copy at the same time): skipped with a note, never an error.
175	 * sockets.json in the working directory (or reserve: a layout or path; null for none) reserves the redstone shops'
176	 * envelopes: every write into one is refused. A part given { carve: true } (the stair joiner) may cut through earlier parts' floors and ceilings for its
177	 * stairwells: cells with air straight above or below. Walls stay refused.
178	 *   runParts(g, [["shell", shell.build], ["stairs", stairs.build, { carve: true }], ["garden", garden.build]],
179	 *     { palette: "palette.json", roof: "roof.json" })
180	 */
181	export function runParts(g, list, { palette, roof, reserve, log = console.log, report = "parts-report.json" } = {}) {
182	  // `mcd variant` rebuilds a finished build from its code with a roof change ($MCD_ROOF: JSON laid over roof.json)
183	  // and leaves the build's own reports alone ($MCD_PARTS_REPORT=none)
184	  if (process.env.MCD_PARTS_REPORT === "none") report = null;
185	  if (roof && process.env.MCD_ROOF) {
186	    const base = typeof roof === "string" ? (existsSync(roof) ? JSON.parse(readFileSync(roof, "utf8")) : null) : roof;
187	    if (base) roof = { ...base, ...JSON.parse(process.env.MCD_ROOF) };
188	  }
189	  const pal = typeof palette === "string" ? (existsSync(palette) ? JSON.parse(readFileSync(palette, "utf8")) : null) : palette;
190	  const allowed = pal ? new Set([...Object.values(pal.roles ?? {}).flat(), ...(pal.objects ?? [])].map(ns)) : null;
191	  const owned = new Set(), reports = [], cellsByPart = {}, trussJob = [];
192	  // redstone shop sockets (sockets.json, mcd sockets layout): their envelopes are reserved before any part runs, so a
193	  // write into one is refused like a write into an earlier part, and a carving part can't free them either
194	  const sock = reserve === undefined ? (existsSync("sockets.json") ? "sockets.json" : null) : reserve;
195	  const reserved = sock ? reservedCells(typeof sock === "string" ? JSON.parse(readFileSync(sock, "utf8")) : sock) : new Set();
196	  for (const k of reserved) owned.add(k);
197	  if (reserved.size) {
198	    // the fit-out the spec fixes (glass wall lines and back walls, a spawn-proof pit floor, the counters) is laid first
199	    // and locked like the envelopes: no part can swap a wall line's glass for a conductor
200	    const L = typeof sock === "string" ? JSON.parse(readFileSync(sock, "utf8")) : sock;
201	    // the ground laid before runParts (a site filled solid to the street) is dug out of the envelopes
202	    let dug = 0;
203	    for (const key of reserved) { const p = key.split(",").map(Number); if (g.inBounds(...p) && !/(^|:)(cave_)?air$/.test(g.blockAt(...p))) { g.set(...p, "air"); dug++; } }
204	    if (dug) log(`sockets: ${dug} cells of ground dug out of the envelopes`);
205	    const fit = socketFitout(L, L.fitout ?? {});
206	    for (const c of fit) { g.set(...c); owned.add(`${c[0]},${c[1]},${c[2]}`); }
207	    log(`sockets: ${reserved.size} cells reserved for the shops' redstone, ${fit.length} fit-out blocks laid (${typeof sock === "string" ? sock : "layout"})`);
208	  }
209	  for (const [name, build, opts0] of list) {
210	    // the stair joiner carves: a part given { carve: true }, or named for stairs (scaffolds rebuild the list their
211	    // own way, so the name is what survives)
212	    const opts = opts0 ?? (/stair/i.test(name) && !/^room:/i.test(name) ? { carve: true } : undefined);
213	    const mine = new Set(), refused = [], off = new Map(), carved = [];
214	    const airy = (target, x, y, z) => !target.inBounds(x, y, z) || /(^|:)(cave_)?air$/.test(target.blockAt(x, y, z));
215	    const write = (target, x, y, z, block, state, nbt) => {
216	      const k = `${x},${y},${z}`;
217	      // a carving part (the stair joiner) may cut through an earlier part's floors and ceilings: a cell with air
218	      // straight above or below it. Walls (solid above and below) stay refused.
219	      if (owned.has(k) && opts?.carve && !reserved.has(k) && (airy(target, x, y + 1, z) || airy(target, x, y - 1, z))) { owned.delete(k); carved.push([x, y, z]); }
220	      if (owned.has(k)) { refused.push([x, y, z, ns(block).replace("minecraft:", ""), target.blockAt(x, y, z).replace("minecraft:", "")]); return; }
221	      const b = ns(block);
222	      if (allowed && b !== "minecraft:air" && b !== "minecraft:cave_air" && !allowed.has(b)) off.set(b, (off.get(b) ?? 0) + 1);
223	      target.set(x, y, z, block, state, nbt);
224	      mine.add(k);
225	    };
226	    const view = new Proxy(g, {
227	      get(target, prop) {
228	        if (prop === "set") return (x, y, z, block, state, nbt) => { write(target, x, y, z, block, state, nbt); return view; };
229	        if (prop === "unset") return (x, y, z) => { write(target, x, y, z, "minecraft:air"); return view; };
230	        if (prop === "fill") return (a, b, block, state) => {
231	          for (let x = Math.min(a[0], b[0]); x <= Math.max(a[0], b[0]); x++)
232	            for (let y = Math.min(a[1], b[1]); y <= Math.max(a[1], b[1]); y++)
233	              for (let z = Math.min(a[2], b[2]); z <= Math.max(a[2], b[2]); z++) write(target, x, y, z, block, state);
234	          return view;
